// === Tab: mySketch ===
let points = [];
t = 0.3;

function setup() {
	createCanvas(600, 600);
	for (let i = 0; i < 40; i++) {
		points.push(new Point(width / 2, random(height)));
	}
}

function draw() {
	//background(220, 220, 250, 10);
	translate(width / 2, height / 2);
	for (let p of points) {
		p.move();
		p.show();
	}
}
class Point {
	constructor(x, y) {
		this.x = x;
		this.y = y;
		this.size = random(2, 80);
		this.angle = 0;
	}
	move() {
		let s = sin(frameCount * 0.001 + this.size);
		this.y = map(s, -1, 1, this.size, height - this.size);
		this.x = map(s, -1, 1, this.size, width - this.size);
		rotate(this.angle);
		this.angle += 0.1;
	}
	show() {
		noStroke();
		let c = map(this.size, 2, 80, 0, 255);
		fill(c, c, 120, 35);
		circle(this.x, this.y, this.size);
	}
}

